import{_ as a,o as e,c as o,a3 as r}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"在 MiniTavern 中配置","description":"MiniTavern 连接 Ollama、LM Studio、KoboldCPP、llama.cpp：设置 → 模型连接，填写 OpenAI 兼容 Base URL 与测连。","frontmatter":{"title":"在 MiniTavern 中配置","description":"MiniTavern 连接 Ollama、LM Studio、KoboldCPP、llama.cpp：设置 → 模型连接，填写 OpenAI 兼容 Base URL 与测连。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"在 MiniTavern 中配置 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 连接 Ollama、LM Studio、KoboldCPP、llama.cpp：设置 → 模型连接，填写 OpenAI 兼容 Base URL 与测连。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/connect-app/minitavern"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/connect-app/minitavern"}]]},"headers":[],"relativePath":"connect-app/minitavern.md","filePath":"connect-app/minitavern.md","lastUpdated":1787117554000}'),d={name:"connect-app/minitavern.md"};function l(i,t,n,c,s,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="在-minitavern-中配置" tabindex="-1">在 MiniTavern 中配置 <a class="header-anchor" href="#在-minitavern-中配置" aria-label="Permalink to &quot;在 MiniTavern 中配置&quot;">​</a></h1><p>本文对应 App 内路径：<strong>设置 → 模型 → 模型连接</strong>。</p><h2 id="新建连接" tabindex="-1">新建连接 <a class="header-anchor" href="#新建连接" aria-label="Permalink to &quot;新建连接&quot;">​</a></h2><ol><li>打开 MiniTavern → 底部 <strong>设置</strong>。</li><li>进入 <strong>模型</strong> → <strong>模型连接</strong>。</li><li>点右上角 <strong>新建</strong>。</li><li><strong>模型平台</strong> 选择 <strong>自定义</strong>（OpenAI 兼容 / 自定义 Base URL，以当前版本选项文案为准）。</li><li>按你的工具填写下表，保存；若支持 <strong>测连</strong>，先测连再设为默认。</li></ol><h2 id="各工具示例" tabindex="-1">各工具示例 <a class="header-anchor" href="#各工具示例" aria-label="Permalink to &quot;各工具示例&quot;">​</a></h2><p>将 <code>YOUR_PC_IP</code> 换成电脑局域网 IP（不要用 <code>localhost</code>）。</p><table tabindex="0"><thead><tr><th>工具</th><th>Base URL 示例</th><th>模型名</th><th>API Key</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ollama/lan">Ollama</a></td><td><code>http://YOUR_PC_IP:11434/v1</code></td><td><code>ollama list</code> 中的名称</td><td>可空或 <code>ollama</code></td></tr><tr><td><a href="/ultra_guides/lmstudio/server">LM Studio</a></td><td><code>http://YOUR_PC_IP:1234/v1</code></td><td>Local Server 中的 id</td><td>可空</td></tr><tr><td><a href="/ultra_guides/koboldcpp/server">KoboldCPP</a></td><td><code>http://YOUR_PC_IP:5001/v1</code></td><td><code>/v1/models</code> 中的 id</td><td>可空</td></tr><tr><td><a href="/ultra_guides/llamacpp/server">llama.cpp</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>server 返回的 id</td><td>可空</td></tr><tr><td><a href="/ultra_guides/localai/install">LocalAI</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>LocalAI 配置名</td><td>按是否鉴权</td></tr><tr><td><a href="/ultra_guides/jan/install">Jan</a></td><td>应用 API 页显示的地址</td><td>列表中的 id</td><td>按应用设置</td></tr><tr><td><a href="/ultra_guides/textgen/install">text-generation-webui</a></td><td><code>http://YOUR_PC_IP:端口/v1</code></td><td>扩展返回的 id</td><td>按扩展设置</td></tr></tbody></table><p>别名可自定，例如 <code>家里Ollama</code>、<code>书房Kobold</code>。</p><h2 id="设为默认并开聊" tabindex="-1">设为默认并开聊 <a class="header-anchor" href="#设为默认并开聊" aria-label="Permalink to &quot;设为默认并开聊&quot;">​</a></h2><ol><li>在模型连接列表中设为 <strong>默认</strong>。</li><li>导入或选择角色卡，进入聊天发一条消息。</li><li>电脑端对应工具应出现请求活动；App 内应收到流式或完整回复。</li></ol><h2 id="会话级覆盖-可选" tabindex="-1">会话级覆盖（可选） <a class="header-anchor" href="#会话级覆盖-可选" aria-label="Permalink to &quot;会话级覆盖（可选）&quot;">​</a></h2><p>某个聊天要临时换本地模型：在聊天设置里覆盖全局默认模型连接 / 参数。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li><strong>禁止</strong> 在手机上填 <code>http://localhost:...</code> 或 <code>http://127.0.0.1:...</code>。</li><li>URL 末尾建议带 <code>/v1</code>，不要填到 <code>/chat/completions</code>。</li><li>电脑休眠、合盖、切网络后 IP 可能变化。</li><li>端口以你实际开启的为准，上表仅为常见默认。</li></ul><p>连不上请看 <a href="/ultra_guides/troubleshoot">排错对照表</a>。选工具见 <a href="/ultra_guides/local/tools">工具总览</a>。</p>',15)])])}const m=a(d,[["render",l]]);export{u as __pageData,m as default};
